import { IconArrowDownward } from "@airbus/icons";
import { focus, svgColor, svgUri } from "../../helpers";
import { StyleFn } from "..";

export const Table: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;
  const { asset } = theme;
  const { focusWithPseudo } = focus(theme, mode);

  const resizerGrip = {
    content: "''",
    position: "absolute",
    width: size.spacing[8],
    height: "100%",
    top: 0,
    bottom: 0,
  };

  return {
    root: {
      width: "100%",
      height: "100%",
      display: "table",
      tableLayout: "fixed",
      position: "relative",
      textAlign: "left",
      verticalAlign: "middle",
      fontSize: font.size.small,
      color: color.text.neutral.default[mode],
      borderSpacing: 0,
      borderCollapse: "collapse",
      // force default display for native html table elements
      "& td, & th": {
        display: "table-cell !important",
      },
    },
    container: {
      width: "100%",
      height: "100%",
    },
    _condensed: {
      "& $head": {
        minHeight: size.spacing[40],
        "& $row, &:before, &:after": {
          height: size.spacing[40],
        },
      },
      "& $row": {
        height: size.spacing[32],
      },
      "& $cell": {
        "@supports (-webkit-line-clamp: 2)": {
          display: "block",
          whiteSpace: "nowrap",
        },
      },
    },
    head: {
      extend: [focusWithPseudo()],
      border: 'none', //override border
      borderBottom: `1px solid ${color.border.neutral.default[mode]}`,
      position: "relative",
      minHeight: size.spacing[48],
      color: color.text.neutral.default,
      overflow: "hidden",
      "& $row": {
        height: size.spacing[48],
        backgroundColor: color.surface.componentonbackground.minimal[mode],
      },
    },
    body: {
      minHeight: size.spacing[40],
      overflow: "auto",
      "& $row:first-child": { boxShadow: "none" },
      "& $body": {
        boxShadow: "none",
      },
      "& $row:hover": {
        backgroundColor: color.surface.interaction.hover[mode],
      }
    },
    row: {
      boxSizing: "border-box",
      height: size.spacing[40],
      backgroundColor: color.surface.interaction.default[mode], //rows color
      "&:nth-of-type(even):not(:hover)": {
        backgroundColor: color.surface.componentbackground.minimal[mode],
      },
    },
    row_dividers: {
      boxShadow: `0px 1px 0px inset ${color.palette.coolgrey[20]}`,
    },
    row_clickable: {
      cursor: "pointer",
    },
    row_expanded: {
      position: "relative",
      padding: `${size.spacing[8]} ${size.spacing[16]}`,
      "&:nth-of-type(odd)": {
        backgroundColor: color.surface.componentbackground.minimal[mode],
      },
    },
    row_expanded_even: {
      display: "none",
    },
    row_selected: {
      // increase specificity
      "$row_selected&:not(:hover)": {
        backgroundColor: color.surface.interaction.active[mode],
      },
      "&:nth-of-type(even):not(:hover)": {
        backgroundColor: color.surface.interaction.active[mode],
      },
    },
    cell: {
      padding: `0 ${size.spacing[16]}`,
      margin: "auto 0",
      lineHeight: font.lineheight.xxsmall,
      // limit content to one line with ellipsis
      overflow: "hidden",
      textOverflow: "ellipsis",
      whiteSpace: "nowrap",
      // // two lines for browsers that support line-clamp
      "@supports (-webkit-line-clamp: 2)": {
        whiteSpace: "initial",
        display: "-webkit-box",
        boxOrient: "vertical",
        lineClamp: 2,
      },
    },
    cell_head: {
      display: "flex",
      alignItems: "center",
      padding: `${size.spacing[8]} ${size.spacing[16]}`,
      lineHeight: font.lineheight.xxsmall,
      position: "relative",
      fontWeight: font.weight.bold,
      "&:hover": {
        backgroundColor: color.surface.interaction.hover[mode],
      },
      "&:hover $resizer": {
        opacity: 1,
      },
      // needed because of resizer invisible grip
      "&:last-child": {
        overflow: "hidden",
      },
    },
    cell_right: {
      textAlign: "right",
      justifyContent: "flex-end",
    },
    cell_checkbox: {
      padding: size.spacing[8],
      paddingTop: size.spacing[8],
      paddingLeft: size.spacing[12],
      width: size.spacing[40],
      flex: "unset !important",
    },
    cell_expand: {
      padding: size.spacing[8],
      width: size.spacing[40],
    },
    expandBtn: {},
    expandBtn_collapse: {
      transform: "rotate(180deg)",
    },
    empty: {
      paddingTop: size.spacing[128],
      marginBottom: size.spacing[16],
      backgroundImage: svgUri(asset.image.box.value, true),
      backgroundRepeat: "no-repeat",
      backgroundPosition: `center ${size.spacing[16]}`,
      backgroundSize: size.spacing[112],
      textAlign: "center",
      fontSize: font.size["heading-6"],
      color: color.text.neutral.strong[mode],
      "& > *": { marginTop: size.spacing[16], marginBottom: 0 }
    },
    loading: {
      position: "absolute",
      top: 0,
      bottom: 0,
      left: 0,
      right: 0,
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      backgroundColor: "#00000020",
    },
    pagination: {
      paddingTop: size.spacing[16],
    },
    resizer: {
      position: "absolute",
      top: 0,
      right: 0,
      zIndex: 1,
      background: color.border.accent.focus[mode],
      width: 1,
      height: "100%",
      cursor: "ew-resize",
      /* prevents from scrolling while dragging on touch devices */
      touchAction: "none",
      opacity: 0,
      "&:hover": {
        width: size.spacing[4],
        right: -1,
      },
      "&:before": {
        ...resizerGrip,
        left: `calc(-${size.spacing[8]})`,
      },
      "&:after": {
        ...resizerGrip,
        right: `calc(-${size.spacing[8]})`,
      },
    },
    resizer_resizing: {
      opacity: 1,
      width: size.spacing[4],
      right: -1,
    },
  };
};

export const SortLabel: StyleFn = (theme, mode) => {
  const { font, color, size, opacity } = theme;

  return {
    root: {
      color: color.text.neutral.default[mode],
      fontWeight: font.weight.bold,
      fontSize: font.size.small,
      position: "relative",
      cursor: "pointer",
      display: "flex",
      alignItems: "center",
      whiteSpace: "nowrap",
      textOverflow: "hidden",
    },
    arrow: {
      position: "relative",
      width: size.spacing[16],
      height: size.spacing[16],
      marginLeft: size.spacing[8],
      opacity: opacity.disabled,
      "&:before": {
        position: "absolute",
        content: "''",
        top: 0,
        right: 0,
        bottom: 0,
        left: 0,
        backgroundSize: size.spacing[16],
        backgroundPosition: "center center",
        backgroundImage: svgUri(
          svgColor(IconArrowDownward.data, color.text.accent.corporate[mode])
        ),
        transition:
          "opacity 200ms cubic-bezier(0.4, 0, 0.2, 1) 0ms,transform 200ms cubic-bezier(0.4, 0, 0.2, 1) 0ms",
      },
    },
    index: {
      fontSize: "0.625rem",
      color: color.text.accent.corporate[mode],
      position: "absolute",
      top: `calc(-${size.spacing[8]})`,
      right: `calc(-${size.spacing[8]})`,
    },
    _right: {
      flexDirection: "row-reverse",
      "& $arrow": {
        marginLeft: 0,
        marginRight: size.spacing[8],
      },
      "& $index": {
        left: `calc(-${size.spacing[8]})`,
        right: "auto",
      },
    },
    _active: {
      fontWeight: font.weight.bold,
      "& $arrow":{
        opacity: 1,
      },
      "& $arrow:before": {
        backgroundImage: svgUri(svgColor(IconArrowDownward.data, color.text.accent.corporate[mode])),
        opacity: 1,
      },
    },
    _asc: {
      "& $arrow:before": {
        transform: "rotate(180deg)",
      },
    },
  };
};
